/* @lc app=leetcode id=2257 lang=kotlin */ class Solution { fun countUnguarded(m: Int, n: Int, guards: Array<IntArray>, walls: Array<IntArray>): Int = Array(m) { IntArray(n) }.apply { walls.forEach { this[it[0]][it[1]] = 2 }.let { guards.forEach { this[it[0]][it[1]] = 1 } }.let { guards.forEach { (r, c) -> listOf(-1 to 0, 1 to 0, 0 to -1, 0 to 1).forEach { (dr, dc) -> generateSequence(r + dr to c + dc) { it.first + dr to it.second + dc }.takeWhile { it.first in 0 until m && it.second in 0 until n && this[it.first][it.second] < 1 }.forEach { this[it.first][it.second] = -1 } } } } }.sumOf { row -> row.count { it == 0 } } }